    );
  }

  async markCompleted(client: pg.PoolClient, requestId: string): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='completed', last_error=NULL, completed_at=COALESCE(completed_at,now()),
           lease_expires_at=NULL, updated_at=now()
       WHERE id=$1
       RETURNING id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at`,
      [requestId],
    );
    return result.rows[0]!;
  }

  async customerExists(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async collect(merchantId: string, customerId: string): Promise<CollectedCustomerPii> {
    const customer = await pool.query<{
      email: string; name: string; phone: string | null; external_reference: string;
    }>(
      `SELECT email,name,phone,external_reference FROM customers.customers
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    const row = customer.rows[0];
    const contacts = await pool.query<{ value: string }>(
      `SELECT value FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    const addresses = await pool.query<{ line1: string; line2: string | null; city: string }>(
      `SELECT line1,line2,city FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    const methods = await pool.query<{ billing_name: string | null; provider_token: string }>(
      `SELECT billing_name,provider_token FROM customers.payment_method_refs
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    const documents = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    const imports = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM customers.customer_imports WHERE merchant_id=$1`,
      [merchantId],
    );
    return {
      customerId,
      merchantId,
      emails: row ? [row.email] : [],
      names: row ? [row.name] : [],
      phones: row?.phone ? [row.phone] : [],
      contacts: contacts.rows.map((item) => item.value),
      addresses: addresses.rows.flatMap((item) => [item.line1, item.line2, item.city].filter((value): value is string => Boolean(value))),
      billingNames: methods.rows.map((item) => item.billing_name).filter((value): value is string => Boolean(value)),
      tokens: methods.rows.map((item) => item.provider_token),
      references: row ? [row.external_reference] : [],
      documentKeys: [...new Set([
        ...documents.rows.map((item) => item.object_key),
        ...imports.rows.map((item) => item.object_key),
      ])],
    };
  }

  async redactDatabase(
    client: pg.PoolClient, merchantId: string, customerId: string, collected: CollectedCustomerPii,
  ): Promise<void> {
    const pii = piiValuesFrom(collected);
    await client.query(
      `UPDATE customers.customers
       SET email=$3, name=$4, phone=NULL, external_reference=$5, metadata='{}'::jsonb,
           status='erased', version=version+1, updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId, erasedEmail(customerId), REDACTED, erasedReference(customerId)],
    );
    await client.query(
      `UPDATE customers.addresses
       SET line1=$3, line2=NULL, city=$3, region=NULL, postal_code='00000'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, REDACTED],
    );
    await client.query(
      `UPDATE customers.contacts SET value=$3 WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, REDACTED],
    );
    await client.query(
      `UPDATE customers.payment_method_refs
       SET provider_token=$3, billing_name=$4, billing_address=NULL, last4=NULL, status='erased'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, `erased-${customerId}`, REDACTED],
    );
    await this.redactJsonColumn(client,
      `UPDATE payments.payment_intents SET customer_snapshot=$3, description=$4, updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      merchantId, customerId, pii, 'customer_snapshot', 'description',
    );
    await this.redactJsonColumn(client,
      `UPDATE payments.payment_attempts SET request_payload=$3, response_payload=$4
       WHERE merchant_id=$1 AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      merchantId, customerId, pii, 'request_payload', 'response_payload',
    );
    await client.query(
      `UPDATE payments.refunds SET customer_email=$3
       WHERE merchant_id=$1 AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId, erasedEmail(customerId)],
    );
    await this.redactJsonColumn(client,
      `UPDATE payments.disputes SET evidence=$3
       WHERE merchant_id=$1 AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      merchantId, customerId, pii, 'evidence',
    );
    await this.redactJsonColumn(client,
      `UPDATE payments.invoices SET billing_snapshot=$3
       WHERE merchant_id=$1 AND customer_id=$2`,
      merchantId, customerId, pii, 'billing_snapshot',
    );
    await this.redactTextRows(client,
      `SELECT id,description FROM payments.ledger_entries
       WHERE merchant_id=$1 AND (
         reference_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)
         OR reference_id IN (
           SELECT r.id FROM payments.refunds r
           JOIN payments.payment_intents p ON p.id=r.payment_intent_id
           WHERE p.merchant_id=$1 AND p.customer_id=$2
         )
       )`,
      `UPDATE payments.ledger_entries SET description=$2 WHERE id=$1`,
      merchantId, customerId, pii,
    );
    await this.redactJsonColumn(client,
      `UPDATE platform.audit_logs SET metadata=$3
       WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2::text`,
      merchantId, customerId, pii, 'metadata',
    );
    await this.redactJsonColumn(client,
      `UPDATE operations.outbox_events SET payload=$3
       WHERE merchant_id=$1 AND (
         aggregate_id=$2 OR payload->>'customerId'=$2::text OR payload->>'customer_id'=$2::text
       )`,
      merchantId, customerId, pii, 'payload',
    );
    await this.redactJsonColumn(client,
      `UPDATE operations.analytics_events SET email=$3, properties=$4, anonymous_id=$5
       WHERE merchant_id=$1 AND customer_id=$2`,
      merchantId, customerId, pii, 'email', 'properties',
    );
    await client.query(
      `UPDATE operations.analytics_events SET email=$3, anonymous_id=$4
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, erasedEmail(customerId), `anon_${customerId}`],
    );
    await this.redactJsonColumn(client,
      `UPDATE operations.jobs SET payload=$3
       WHERE merchant_id=$1 AND (payload->>'customerId'=$2::text OR payload->>'customer_id'=$2::text)`,
      merchantId, customerId, pii, 'payload',
    );
    await this.redactSupport(client, merchantId, customerId, pii);
    await this.deleteOperationalPii(client, merchantId, customerId);
    await this.deleteImportArtifacts(client, merchantId, customerId);
  }

  private async redactJsonColumn(
    client: pg.PoolClient,
    selectOrUpdate: string,
    merchantId: string,
    customerId: string,
    pii: string[],
    ...columns: string[]
  ): Promise<void> {
    if (columns.length === 1 && selectOrUpdate.startsWith('UPDATE')) {
      const rows = await this.loadForRedaction(client, selectOrUpdate, merchantId, customerId, columns);
      for (const row of rows) {
        const next = redactJson(row[columns[0]!], pii);
        await client.query(
          selectOrUpdate, [merchantId, customerId, next],
        );
        break;
      }
      if (rows.length === 0) {
        await client.query(selectOrUpdate, [merchantId, customerId, redactJson({}, pii)]);
      } else {
        for (const row of rows) {
          await this.applyRowRedaction(client, selectOrUpdate, merchantId, customerId, row, columns, pii);
        }
      }
      return;
    }
    const rows = await this.loadForRedaction(client, selectOrUpdate, merchantId, customerId, columns);
    for (const row of rows) {
      await this.applyRowRedaction(client, selectOrUpdate, merchantId, customerId, row, columns, pii);
    }
  }

  private async loadForRedaction(
    client: pg.PoolClient,
    updateSql: string,
    merchantId: string,
    customerId: string,
    columns: string[],
  ): Promise<Array<Record<string, unknown>>> {
    const from = updateSql.match(/UPDATE\s+[\w.]+/i)?.[0]?.replace(/UPDATE/i, 'SELECT id,') ?? '';
    const table = updateSql.match(/UPDATE\s+([\w.]+)/i)?.[1];
    const where = updateSql.split(/WHERE/i)[1];
    if (!table || !where) return [];
    const selected = columns.includes('id') ? columns.join(',') : `id,${columns.join(',')}`;
    const result = await client.query(
      `SELECT ${selected} FROM ${table} WHERE ${where.split('$3')[0].replace(/,\s*$/, '')}`,
      [merchantId, customerId],
    );
    return result.rows as Array<Record<string, unknown>>;
    void from;
  }

  private async applyRowRedaction(
    client: pg.PoolClient,
    updateSql: string,
    merchantId: string,
    customerId: string,
    row: Record<string, unknown>,
    columns: string[],
    pii: string[],
  ): Promise<void> {
    const table = updateSql.match(/UPDATE\s+([\w.]+)/i)?.[1];
    if (!table || !row.id) return;
    const assignments = columns.map((column, index) => `${column}=$${index + 2}`).join(',');
    const values = columns.map((column) => {
      const current = row[column];
      if (column === 'description' || column === 'email' || column === 'anonymous_id') {
        return typeof current === 'string' ? redactText(current, pii) : current;
      }
      return redactJson(current, pii);
    });
    await client.query(
      `UPDATE ${table} SET ${assignments} WHERE id=$1`,
      [row.id, ...values],
    );
    void merchantId;
    void customerId;
  }

  private async redactTextRows(
    client: pg.PoolClient,
    selectSql: string,
    updateSql: string,
    merchantId: string,
    customerId: string,
    pii: string[],
  ): Promise<void> {
    const result = await client.query<{ id: string; description: string }>(selectSql, [merchantId, customerId]);
    for (const row of result.rows) {
      const next = redactText(row.description, pii);
      if (next !== row.description) await client.query(updateSql, [row.id, next]);
    }
  }

  private async redactSupport(
    client: pg.PoolClient, merchantId: string, customerId: string, pii: string[],
  ): Promise<void> {
    const messages = await client.query<{ id: string; body: string }>(
      `SELECT id,body FROM customers.support_messages
       WHERE merchant_id=$1 AND (author_id=$2 OR ticket_id IN (
         SELECT ticket_id FROM customers.support_participants WHERE customer_id=$2
       ))`,
      [merchantId, customerId],
    );
    for (const message of messages.rows) {
      const body = redactText(message.body, pii) ?? REDACTED;
      await client.query(`UPDATE customers.support_messages SET body=$2, attachments='[]'::jsonb WHERE id=$1`, [message.id, body]);
    }
    const tickets = await client.query<{ id: string; subject: string }>(
      `SELECT t.id,t.subject FROM customers.support_tickets t
       JOIN customers.support_participants p ON p.ticket_id=t.id
       WHERE t.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId],
    );
    for (const ticket of tickets.rows) {
      const subject = redactText(ticket.subject, pii) ?? REDACTED;
      const others = await client.query(
        `SELECT 1 FROM customers.support_participants WHERE ticket_id=$1 AND customer_id<>$2`,
        [ticket.id, customerId],
      );
      if (!others.rowCount) {
        await client.query(`UPDATE customers.support_tickets SET subject=$2 WHERE id=$1`, [ticket.id, subject]);
      }
    }
  }

  private async deleteOperationalPii(
    client: pg.PoolClient, merchantId: string, customerId: string,
  ): Promise<void> {
    await client.query(
      `DELETE FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM operations.dead_letters
       WHERE payload->>'customerId'=$1 OR payload->>'customer_id'=$1`,
      [customerId],
    );
  }

  private async deleteImportArtifacts(
    client: pg.PoolClient, merchantId: string, customerId: string,
  ): Promise<void> {
    const imports = await client.query<{ id: string; object_key: string }>(
      `SELECT id,object_key FROM customers.customer_imports WHERE merchant_id=$1`,
      [merchantId],
    );
    for (const item of imports.rows) {
      const related = item.object_key.includes(customerId)
        || (await this.manifestMentionsCustomer(client, item.object_key, customerId));
      if (!related) continue;
      await client.query(`DELETE FROM operations.document_manifests WHERE object_key=$1`, [item.object_key]);
      await client.query(`DELETE FROM customers.customer_imports WHERE id=$1`, [item.id]);
    }
  }

  private async manifestMentionsCustomer(
    client: pg.PoolClient, objectKey: string, customerId: string,
  ): Promise<boolean> {
    const result = await client.query(
      `SELECT 1 FROM operations.document_manifests
       WHERE object_key=$1 AND (customer_id=$2 OR metadata->>'importId' IS NOT NULL)`,
      [objectKey, customerId],
    );
    return Boolean(result.rowCount);
  }
}
"}

